/**
 * Rig profiles for the prepared Mixamo instructor avatars.
 *
 * A profile is generated by `scripts/prepare_avatars.py` from the bytes that ship,
 * so it cannot describe a different model than the one next to it. These helpers
 * validate that agreement at load time and expose the facts the viewer needs
 * (bone order, landmarks, height, facing) without hard-coding any bone name.
 */
import male from './profiles/male.json';
import female from './profiles/female.json';

export type AvatarId = 'male' | 'female';
export const AVATAR_IDS: AvatarId[] = ['male', 'female'];

export type AvatarBone = {
  name: string;
  parent: string | null;
  /** Local rest translation, in the rig's own units before the armature scale. */
  t: number[];
  /** Local rest rotation, glTF order (x, y, z, w). */
  r: number[];
  s: number[];
  /** Inverse bind matrix, row-major, translation in the last column. */
  ibm: number[];
};

export type AvatarLandmark = {bone: string; rest: [number, number, number]};

export type AvatarProfile = {
  schema: number;
  avatar_id: AvatarId;
  display_name: string;
  asset: {
    file: string;
    sha256: string;
    bytes: number;
    asset_version: string;
    prep_version: string;
  };
  source: {file: string; sha256: string};
  units: {world: string; note: string};
  rig: {
    family: string;
    joint_count: number;
    root_bone: string;
    matrix_convention: string;
    /** The armature node's own transform. Bone data is in centimetres under a 0.01 scale. */
    armature: {t: number[]; r: number[]; s: number[]};
    bones: AvatarBone[];
  };
  landmarks: Record<string, AvatarLandmark>;
  measurements: {
    standing_height: number;
    floor_y: number;
    hip_height: number;
    head_top_height: number;
    bounds: {min: number[]; max: number[]};
  };
  orientation: {up: number[]; forward: number[]; facing_yaw_degrees: number; note: string};
  bind_pose: {pose: string; clips: number};
};

const RAW: Record<AvatarId, AvatarProfile> = {
  male: male as unknown as AvatarProfile,
  female: female as unknown as AvatarProfile,
};

/** Required landmarks. The viewer resolves these by name, never by array position. */
export const REQUIRED_LANDMARKS = [
  'hips', 'head', 'head_top',
  'left_wrist', 'right_wrist',
  'left_ankle', 'right_ankle',
  'left_toe', 'right_toe',
] as const;

export class AvatarProfileError extends Error {}

export function validateProfile(profile: AvatarProfile): AvatarProfile {
  const fail = (message: string): never => {
    throw new AvatarProfileError(`${profile.avatar_id ?? 'unknown avatar'}: ${message}`);
  };
  if (profile.schema !== 1) fail(`unsupported profile schema ${profile.schema}`);
  if (!profile.asset?.file?.endsWith('.glb')) fail('asset filename is not a GLB');
  if (!/^[0-9a-f]{64}$/.test(profile.asset.sha256)) fail('asset hash is not a sha256 digest');
  if (!profile.rig?.bones?.length) fail('profile has no bones');

  const names = new Set<string>();
  for (const bone of profile.rig.bones) {
    if (!/^[A-Za-z0-9_]+$/.test(bone.name)) fail(`bone name ${bone.name} is not loader-safe`);
    if (names.has(bone.name)) fail(`duplicate bone name ${bone.name}`);
    names.add(bone.name);
    if (bone.ibm.length !== 16) fail(`${bone.name} has a malformed bind matrix`);
    if (bone.r.length !== 4 || bone.t.length !== 3 || bone.s.length !== 3) {
      fail(`${bone.name} has a malformed rest transform`);
    }
    const length = Math.hypot(...bone.r);
    if (Math.abs(length - 1) > 1e-3) fail(`${bone.name} rest rotation is not a unit quaternion`);
  }
  if (profile.rig.joint_count !== profile.rig.bones.length) fail('joint_count disagrees with the bone list');
  if (!names.has(profile.rig.root_bone)) fail(`root bone ${profile.rig.root_bone} is missing`);

  for (const bone of profile.rig.bones) {
    // Parents are declared before children, which the retargeter and the viewer rely on.
    if (bone.parent !== null && !names.has(bone.parent)) fail(`${bone.name} has unknown parent ${bone.parent}`);
  }
  for (const key of REQUIRED_LANDMARKS) {
    const landmark = profile.landmarks?.[key];
    if (!landmark) fail(`landmark ${key} is missing`);
    if (!names.has(landmark!.bone)) fail(`landmark ${key} points at missing bone ${landmark!.bone}`);
  }
  const height = profile.measurements?.standing_height;
  if (!(height > 1 && height < 2.5)) fail(`implausible standing height ${height}`);
  if (Math.abs(profile.orientation.forward[1]) > 1e-6) fail('forward axis is not horizontal');
  return profile;
}

export const AVATAR_PROFILES: Record<AvatarId, AvatarProfile> = {
  male: validateProfile(RAW.male),
  female: validateProfile(RAW.female),
};

export function avatarProfile(id: AvatarId): AvatarProfile {
  return AVATAR_PROFILES[id];
}

/** Bundled asset path. Public files are served from the deployment root. */
export function avatarAssetUrl(id: AvatarId): string {
  return `/avatars/${avatarProfile(id).asset.file}`;
}

export function boneIndex(profile: AvatarProfile): Map<string, number> {
  return new Map(profile.rig.bones.map((bone, index) => [bone.name, index]));
}

export function parentIndex(profile: AvatarProfile): number[] {
  const index = boneIndex(profile);
  return profile.rig.bones.map(bone => (bone.parent === null ? -1 : index.get(bone.parent)!));
}

/** Bone name for a landmark, or null when a profile legitimately lacks it. */
export function landmarkBone(profile: AvatarProfile, key: string): string | null {
  return profile.landmarks[key]?.bone ?? null;
}

export function landmarkRest(profile: AvatarProfile, key: string): [number, number, number] | null {
  const landmark = profile.landmarks[key];
  return landmark ? [...landmark.rest] : null;
}
